import{z as l,x as B,o as r,c as A,q as t,j as s,D as o,d as e,s as i,S as d,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Woodford 利息与价格","description":"","frontmatter":{"title":"Woodford 利息与价格","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/woodford-interest.md","filePath":"econ/woodford-interest.md","lastUpdated":1791413859000}'),p={name:"econ/woodford-interest.md"};function f(h,E,m,c,C,u){const n=B("Mermaid");return r(),A("div",null,[E[2]||(E[2]=t('<h1 id="woodford-利息与价格" tabindex="-1">Woodford 利息与价格 <a class="header-anchor" href="#woodford-利息与价格" aria-label="Permalink to &quot;Woodford 利息与价格&quot;">​</a></h1><div class="epigraph"><p>在现金几乎消失的极限里，货币政策仍能通过利率规则决定价格水平；数量方程不再是操作手册。</p><footer>—— Woodford, Interest and Prices: Foundations of a Theory of Monetary Policy, Princeton University Press, 2003</footer></div><p><a href="/econ/kydland-prescott">上一课</a>（Kydland–Prescott 规则优于权变）。附录对照。主干<a href="/econ/new-keynesian">新凯恩斯粘性价格</a>与<a href="/econ/taylor-rule">泰勒规则</a>已用三方程课本。本篇对照 <strong>Woodford 2003 原书的问题设定</strong>：Wicksell 式的利率主义如何在跨期一般均衡里被写严，以及为何可以几乎不提货币数量。不重做 <a href="/econ/kydland-prescott">Kydland–Prescott</a> 的时间不一致例子——书把承诺与时间一致政策当成工具，而不是再证明一遍规则优于权变。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>货币主义操作把 \\(M\\) 当工具；\\(MV=PY\\) 是沟通装置。1990 年代主要央行已经盯短期名义利率，准备金迁就结算。缺口是理论：若交易对现金的需求可以任意小（cashless limit），价格水平由什么钉住？Woodford 的回答是新维克塞尔：利率相对自然利率的路径，加上价格粘性，决定通胀与产出缺口；利率规则必须满足泰勒原则一类的激进程度，均衡才局部唯一。</p><p>原书是研究生专著，不是一篇 AER。附录对照其问题与方法骨架：跨期 IS、新凯恩斯菲利普斯、利率规则，以及现金的有无不是定价的关键。主干三方程是这本书的课堂压缩。</p><p><span class="marginnote">术语翻译：自然利率 \\(r^*\\) 就是「价格完全灵活时经济应有的实际利率」——可以想成经济的中性档位。政策利率高于它等于踩刹车，低于它等于踩油门；央行的操作说到底是拿 \\(i-r^*\\) 这个差管理需求。</span></p><p><span class="marginnote">自然利率：灵活价格均衡下的实际利率。政策利率高于它，需求收缩。这是 Wicksell 1898 的语言进了 Calvo 价格与欧拉消费。确定性问题：差的规则允许多条通胀路径都自洽；好的规则把预期钉在唯一局部路径上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代表性家庭欧拉给出实际利率与消费增长的关系，即跨期 IS。Calvo 交错定价给出通胀对产出缺口与预期通胀的 NKPC。政策用</p> \\[i_t = i^* + \\phi_\\pi(\\pi_t-\\pi^*)+\\phi_x x_t \\]<p>一类规则替换 LM。货币数量若出现，只作为利率规则的残余（准备金供给迁就）。分析工具是对数线性、理性预期、局部确定性。最优政策章用二次损失逼近福利，讨论通胀目标与承诺下的利率路径，直接接上 1977 年的承诺价值，但对象换成粘性价格的微观福利。</p>',12)),(r(),s(d,null,{default:o(()=>[i(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20IS%5B%22%E8%B7%A8%E6%9C%9F%20IS%22%5D%20--%3E%20SYS%5B%22%E4%B8%89%E6%96%B9%E7%A8%8B%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20PC%5B%22NK%20%E8%8F%B2%E5%88%A9%E6%99%AE%E6%96%AF%22%5D%20--%3E%20SYS%0A%20%20TR%5B%22%E5%88%A9%E7%8E%87%E8%A7%84%E5%88%99%20%2F%20%E6%B3%B0%E5%8B%92%E5%8E%9F%E5%88%99%22%5D%20--%3E%20SYS%0A%20%20SYS%20--%3E%20P%5B%22%E4%BB%B7%E6%A0%BC%E6%B0%B4%E5%B9%B3%E8%B7%AF%E5%BE%84%22%5D%0A%20%20M%5B%22%E8%B4%A7%E5%B8%81%E6%95%B0%E9%87%8F%22%5D%20-.-%3E%7C%22%E9%9D%9E%E6%93%8D%E4%BD%9C%E5%B7%A5%E5%85%B7%22%7C%20SYS%0A"})]),fallback:o(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"与 Friedman 1956 的对照：两者都要长期锚定名义量；Friedman 用稳定的 \\(M\\) 需求，Woodford 用利率规则对通胀的反应。经验上货币需求不稳，反而抬高了利率主义的相对地位——这是读原书时的语境，不是对 1956 的否证演算。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"数字实例：取 \\(i^*=2\\%\\)、\\(\\pi^*=2\\%\\)、\\(\\phi_\\pi=1.5\\)。通胀升到 \\(3\\%\\) 时，规则要求 \\(i=2\\%+1.5\\times(3\\%-2\\%)=3.5\\%\\)：通胀涨 1 个点，名义利率加 1.5 个点——利率比通胀爬得快，实际利率才会真正收紧，这正是泰勒原则的含义。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,[e("机制是名义锚在预期里，不在印钞机的机械比例。粘性使今天的利率能移动真实需求；理性预期使规则的"),a("strong",null,"未来"),e("部分进入今天的 IS 与 PC。因此沟通与承诺属于同一套工具，数量宽松在零下限才作为替代工具进入——主干"),a("a",{href:"/econ/zlb-unconventional"},"零下限"),e("的位置在此预定，原书已专章处理。")],-1)),E[7]||(E[7]=a("p",null,"Cashless 不是「没有货币」。计价单位仍在，央行仍是唯一能定隔夜利率的机构。消失的是作为数量工具的 \\(M\\)。",-1)),(r(),s(d,null,{default:o(()=>[i(n,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E9%80%9A%E8%83%80%E5%8D%87%E5%88%B0%E7%9B%AE%E6%A0%87%E4%B9%8B%E4%B8%8A%22%5D%20--%3E%20R%5B%22%E6%94%BF%E7%AD%96%E5%88%A9%E7%8E%87%E6%8C%89%20%CF%86%CF%80%20%E5%8A%A0%E7%A0%81%EF%BC%8C%E4%B8%94%E5%8A%A0%E5%B9%85%E5%A4%A7%E4%BA%8E%E9%80%9A%E8%83%80%E6%B6%A8%E5%B9%85%22%5D%0A%20%20R%20--%3E%20REAL%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E9%9A%8F%E4%B9%8B%E4%B8%8A%E8%A1%8C%22%5D%0A%20%20REAL%20--%3E%20DEM%5B%22%E6%80%BB%E9%9C%80%E6%B1%82%E4%B8%8E%E4%BA%A7%E5%87%BA%E7%BC%BA%E5%8F%A3%E6%94%B6%E7%BC%A9%22%5D%0A%20%20DEM%20--%3E%20BACK%5B%22%E9%80%9A%E8%83%80%E5%8E%8B%E5%8A%9B%E5%9B%9E%E8%90%BD%22%5D%0A%20%20BACK%20--%3E%20EQ%5B%22%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%E8%A2%AB%E9%92%89%E5%9C%A8%E5%94%AF%E4%B8%80%E8%B7%AF%E5%BE%84%E4%B8%8A%22%5D%0A%20%20BAD%5B%22%CF%86%CF%80%20%E5%B0%8F%E4%BA%8E%201%EF%BC%9A%E5%88%A9%E7%8E%87%E8%B7%9F%E6%B6%A8%E4%B8%8D%E8%B6%B3%22%5D%20--%3E%20SPI%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E5%8F%8D%E8%80%8C%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SPI%20--%3E%20RUN%5B%22%E9%80%9A%E8%83%80%E8%87%AA%E6%88%91%E5%AE%9E%E7%8E%B0%EF%BC%9A%E5%87%BA%E7%8E%B0%E5%A4%9A%E6%9D%A1%E5%9D%87%E8%A1%A1%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:o(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=t('<p><span class="marginnote">直觉类比：数量论像「水涨船高」——货币多一倍价格就高一倍；利率规则更像恒温器——不直接控制水量，而是盯温度（通胀）自动调油门。只要反应足够猛（大于一比一），温度就被钉住，水位本身反而成了被动结果。</span></p><h3 id="对照-nk-与泰勒-不插入货币课中间" tabindex="-1">对照 NK 与泰勒，不插入货币课中间 <a class="header-anchor" href="#对照-nk-与泰勒-不插入货币课中间" aria-label="Permalink to &quot;对照 NK 与泰勒，不插入货币课中间&quot;">​</a></h3><p>主干<a href="/econ/new-keynesian">新凯恩斯</a>与<a href="/econ/taylor-rule">泰勒规则</a>已经用这套骨架。附录对照 2003 年专论：无外生 \\(M\\) 时价格如何被规则决定；Ramsey 路径一般需承诺，接到 KP。泰勒原理（名义利率对通胀的长期反应大于一）是确定性条件，不是估计系数。金融摩擦、量化宽松细节是后危机文献，不是把全书改写成宏观金融。也不要把限价簿读进政策利率：规则假定存在一个隔夜利率，交易协议在量化栏。</p><p><span class="marginnote">Woodford, <em>Interest and Prices: Foundations of a Theory of Monetary Policy</em>, Princeton University Press, 2003。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 2003 书当成已经包含后危机的足量非常规操作细节；它提供框架，不是 2008 之后的手册。也不要在附录里校准 \\(\\phi_\\pi\\)。不完全竞争加 Calvo 的福利近似依赖特定扰动；异质性、金融摩擦是后文。金融栏的<a href="/econ/reserve-endogenous-money">内生货币</a>解释准备金如何迁就；Woodford 假定迁已经发生，从利率往下写。</p><p>下一篇（也是宏观附录最后一篇）对照银行挤兑原文：利率规则管的是价格水平，不管活期合同的双均衡。</p><p>泰勒原理是确定性条件，不是估计系数。Cashless 里 \\(M\\) 不是操作工具，计价单位仍在。</p><p>承诺把整条路径写进今天的 IS 与菲利普斯；权变只看当期缺口。</p><p>不要把限价簿读进隔夜政策利率。交易协议在量化栏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Woodford 2003：利率规则在近现金极限里决定价格路径。</li><li>骨架是 IS + NKPC + 满足泰勒原则的规则；\\(M\\) 不是操作工具。</li><li>承诺价值接到 KP 1977，对象换成粘性价格福利。</li><li>出处：Woodford, <em>Interest and Prices</em>, 2003。</li></ul>',12))])}const F=l(p,[["render",f]]);export{P as __pageData,F as default};
